const S = (c,o)=>[{type:'SOLID',color:c,opacity:o===undefined?1:o}];

async function T(str,o){
  o=o||{};
  const t=figma.createText();
  const st=o.style||'Regular';
  await figma.loadFontAsync({family:'DM Sans',style:st});
  t.fontName={family:'DM Sans',style:st};
  t.characters=str;
  t.fontSize=o.size||14;
  t.fills=S(o.color||C.ink, o.opacity===undefined?1:o.opacity);
  if(o.lh) t.lineHeight={value:o.lh,unit:'PIXELS'};
  if(o.ls) t.letterSpacing={value:o.ls,unit:'PIXELS'};
  if(o.w){ t.textAutoResize='HEIGHT'; t.resize(o.w,t.height); } else { t.textAutoResize='WIDTH_AND_HEIGHT'; }
  if(o.align) t.textAlignHorizontal=o.align;
  if(o.name) t.name=o.name;
  return t;
}
function AF(name,o){
  o=o||{};
  const f=figma.createFrame(); f.name=name;
  f.layoutMode=o.lm||'HORIZONTAL';
  f.primaryAxisSizingMode=o.pw||'AUTO'; f.counterAxisSizingMode=o.ch||'AUTO';
  f.itemSpacing=o.gap===undefined?0:o.gap;
  f.paddingLeft=o.pl||0; f.paddingRight=o.pr||0; f.paddingTop=o.pt||0; f.paddingBottom=o.pb||0;
  f.primaryAxisAlignItems=o.jc||'MIN'; f.counterAxisAlignItems=o.ac||'MIN';
  f.fills=o.fills===undefined?[]:o.fills;
  if(o.r!==undefined) f.cornerRadius=o.r;
  if(o.stroke){ f.strokes=S(o.stroke); f.strokeWeight=o.sw||1; f.strokeAlign='INSIDE'; }
  if(o.clip!==undefined) f.clipsContent=o.clip;
  if(o.shadow) f.effects=[{type:'DROP_SHADOW',color:o.shadow,offset:o.soff||{x:0,y:4},radius:o.sr||16,spread:0,visible:true,blendMode:'NORMAL'}];
  return f;
}
async function IC(id,size,color,sw){
  const src=await figma.getNodeByIdAsync(id);
  const i=src.createInstance();
  i.resize(size,size);
  i.fills=[];
  const walk=(n)=>{
    if(n.fills&&n.fills.length){ try{ n.fills=n.fills.map(f=>f.type==='SOLID'?{type:'SOLID',color:color,visible:f.visible,opacity:f.opacity}:f);}catch(e){} }
    if(n.strokes&&n.strokes.length){ try{ n.strokes=S(color);}catch(e){} }
    if(n.children) for(const c of n.children) walk(c);
  };
  for(const c of i.children) walk(c);
  return i;
}
