/* light shell instances */
function lightShell(node){
  const i=node.createInstance();
  const walk=(n)=>{if(n.fills&&n.fills.length){try{n.fills=n.fills.map(f=>f.type==='SOLID'?{type:'SOLID',color:C.white,visible:f.visible,opacity:f.opacity}:f);}catch(e){}}
   if(n.strokes&&n.strokes.length){try{n.strokes=S(C.white);}catch(e){}}
   if(n.children)for(const c of n.children)walkW(c);};
  const walkW=(n)=>{if(n.fills&&n.fills.length){try{n.fills=n.fills.map(f=>f.type==='SOLID'?{type:'SOLID',color:C.white,visible:f.visible,opacity:f.opacity}:f);}catch(e){}}
   if(n.strokes&&n.strokes.length){try{n.strokes=S(C.white);}catch(e){}}
   if(n.children)for(const c of n.children)walkW(c);};
  for(const c of i.children) walkW(c);
  return i;
}

/* auth background */
async function authBg(frame){
  const src=await figma.getNodeByIdAsync(MEDIA.auth);
  const i=src.createInstance(); i.name='Photo_Auth_Background';
  i.resize(375,812);
  // set image fill scale mode
  const fix=(n)=>{
    if(n.fills&&n.fills.length){
      try{n.fills=n.fills.map(f=>f.type==='IMAGE'?Object.assign({},f,{scaleMode:'FILL'}):f);}catch(e){}
    }
    if(n.children)for(const c of n.children)fix(c);
  };
  fix(i);
  i.x=0;i.y=0;frame.appendChild(i);
  // overlay: gradient scrim
  const ov=figma.createRectangle(); ov.name='Overlay';
  ov.resize(375,812); ov.x=0;ov.y=0;
  ov.fills=[
    {type:'GRADIENT_LINEAR',gradientTransform:[[0,1,0],[-1,0,1]],gradientStops:[
      {position:0,color:{r:0.020,g:0.031,b:0.039,a:0.94}},
      {position:0.42,color:{r:0.027,g:0.043,b:0.055,a:0.72}},
      {position:0.72,color:{r:0.035,g:0.055,b:0.067,a:0.42}},
      {position:1,color:{r:0.035,g:0.055,b:0.067,a:0.22}}
    ]},
    {type:'SOLID',color:C.scrim,opacity:0.18}
  ];
  frame.appendChild(ov);
  return i;
}

