const ICONS={arrowRight:'1:141',back:'1:142',cart:'1:143',chevron:'1:144',clock:'1:145',close:'1:146',filter:'1:147',lock:'1:148',mail:'1:149',menu:'1:150',minus:'1:151',more:'1:152',plus:'1:153',search:'1:154',starF:'1:155',starO:'1:156',trash:'1:157'};
