function find(nm){return ds.children.find(c=>c.name===nm);}
const chipSet=find('Chip'), tabSet=find('Tab');
function chipVariant(state){return chipSet.children.find(c=>c.name==='State='+state);}
function tabVariant(state){return tabSet.children.find(c=>c.name==='State='+state);}

/* deep find by name */
function deep(node,nm){let r=null;const w=(n)=>{if(r)return;if(n.name===nm){r=n;return;}if(n.children)for(const c of n.children)w(c);};w(node);return r;}
function deepAll(node,nm){const out=[];const w=(n)=>{if(n.name===nm)out.push(n);if(n.children)for(const c of n.children)w(c);};w(node);return out;}
async function setText(node,str){if(!node)return;await figma.loadFontAsync(node.fontName);node.characters=str;}

/* product card instance with overrides */
async function productCard(o){
  const src=find('Product Card');
  const i=src.createInstance(); i.name='Product Card · '+o.name;
  await setText(deep(i,'Name'),o.name);
  await setText(deep(i,'Price'),o.price);
  if(o.rating)await setText(deepAll(i,'Stars')[0]?deep(i,'Stars').children[1]:null,o.rating);
  const img=deep(i,'Image');
  const ph=img.children[0];
  const newSrc=await figma.getNodeByIdAsync(o.photo);
  ph.swapComponent(newSrc);
  ph.resize(o.photoSize||110,o.photoSize||110);
  return i;
}

