function dump(n,d,out){
  const pad='  '.repeat(d);
  let s=pad+n.type+' "'+n.name+'"';
  if(n.type==='TEXT') s+=' = "'+n.characters+'"';
  if(n.type==='INSTANCE') s+=' ->'+n.mainComponent.name;
  out.push(s);
  if(n.children&&d<4) for(const c of n.children) dump(c,d+1,out);
}
